extern "C" unsigned long __cdecl DbgPrint(const char* Format, ...);
#ifndef J2X_INIT_TRACE
#define J2X_INIT_TRACE 0   // default OFF (floods boot log). Set 1 to pinpoint a static-init crash.
#endif

void j2x_initAll()
{
	j2xRegisterRtti();   // instanceof ancestry -- MUST precede any is<T>() (recipe/entity init)
	j2xPrepopulateClassReg();   // pre-fill the class registry at BOOT so RTTI is read-only under MP net threads
#if J2X_INIT_TRACE
	DbgPrint("[INIT] IC\n");
#endif
	IC::initStatics();
#if J2X_INIT_TRACE
	DbgPrint("[INIT] ID\n");
#endif
	ID::initStatics();
#if J2X_INIT_TRACE
	DbgPrint("[INIT] IA\n");
#endif
	IA::initStatics();
#if J2X_INIT_TRACE
	DbgPrint("[INIT] IJ\n");
#endif
	IJ::initStatics();
}

