static bool j2xEq_IK(void* s, const JObject& o) { return ((IK*)s)->equals(o); }
static int j2xHash_IK(void* s) { return ((IK*)s)->hashCode(); }
static bool j2xEq_IL(void* s, const JObject& o) { return s == o.p; }
static int j2xHash_IL(void* s) { return ((IL*)s)->hashCode(); }

void j2xRegisterRtti()
{
	j2xRegisterBase(typeid(IB).name(), typeid(IE).name());
	j2xRegisterBase(typeid(IL).name(), typeid(IK).name());
	j2xRegisterBase(typeid(IM).name(), typeid(IK).name());
	j2xRegisterValue(typeid(IK).name(), j2xEq_IK, j2xHash_IK);
	j2xRegisterValue(typeid(IL).name(), j2xEq_IL, j2xHash_IL);
}

void j2xPrepopulateClassReg()
{
	j2xClassOf(typeid(IA));
	j2xClassOf(typeid(IB));
	j2xClassOf(typeid(IC));
	j2xClassOf(typeid(ID));
	j2xClassOf(typeid(IE));
	j2xClassOf(typeid(IF));
	j2xClassOf(typeid(IG));
	j2xClassOf(typeid(IH));
	j2xClassOf(typeid(IJ));
	j2xClassOf(typeid(IK));
	j2xClassOf(typeid(IL));
	j2xClassOf(typeid(IM));
	j2xClassOf(typeid(IN));
	j2xClassOf(typeid(IP));
	j2xClassOf(typeid(IQ));
}

