#define J2X_RTTI_H
// Registers each class's base/interface ancestry so JObject::is<T>() (instanceof) matches
// subclasses, not just the exact dynamic type. Call ONCE, before any instanceof runs.
void j2xRegisterRtti();
void j2xPrepopulateClassReg();   // pre-fill _j2xClassReg at BOOT (thread-safe RTTI under MP net threads)
#endif // J2X_RTTI_H
